document.getElementById("login_form").addEventListener("submit", function(e) {
  e.preventDefault();

  const email = document.querySelector('#login_form input[type="text"]').value;
  const password = document.querySelector('#login_form #password').value;

  fetch('/api/method/login', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      usr: email,
      pwd: password
    })
  })
  .then(response => response.json())
  .then(data => {
    if (data.full_name) {
      Toastify({
        text: `👋 Welcome ${data.full_name}!`,
        close: true,
        gravity: "top",
        position: "center",
        stopOnFocus: true,
        style: {
          background: "var(--primary-color)",
        }
      }).showToast();

      setTimeout(() => {
        window.location.href = data.home_page || '/';
      }, 1200);
    } else {
      Toastify({
        text: "❌ Invalid credentials. Please try again.",
        close: true,
        gravity: "top",
        position: "center",
        stopOnFocus: true,
        style: {
          background: "var(--primary-color-light)",
        }
      }).showToast();
    }
  })
  .catch(error => {
    console.error('Login error:', error);
    Toastify({
      text: "⚠️ An error occurred during login. Please try again later.",
      close: true,
      gravity: "top",
      position: "center",
      stopOnFocus: true,
      style: {
        background: "var(--primary-color-light)",
      }
    }).showToast();
  });
});


window.onload = function () {
  if (page_data.user && page_data.user !== "Guest") {
    const urlParams = new URLSearchParams(window.location.search);
    const redirectTo = urlParams.get('redirect-to');

    window.location.href = redirectTo || '/profile';
  }
  const showPasswordCheckbox = document.getElementById("show_password");
  const passwordInput = document.getElementById("password");

  if (showPasswordCheckbox && passwordInput) {
    showPasswordCheckbox.setAttribute('type', 'checkbox');

    showPasswordCheckbox.addEventListener("change", function () {
      if (this.checked) {
        passwordInput.setAttribute('type', 'text');
      } else {
        passwordInput.setAttribute('type', 'password');
      }
    });
  }
};
